const stageLabels:Record<SimStage,string>={contract:"Contract",supplier:"Supplier",production:"Production",quality:"QA/Lab",warehouse:"Warehouse",transport:"Transport",port:"Port/Terminal",loading:"Loading/Survey",vessel:"Vessel/Voyage",documents:"Export Documents",customs:"Customs",settlement:"Finance/Settlement"};
const stageActions:Record<SimStage,string>={contract:"Review approved contract baseline and amendment history.",supplier:"Confirm supplier commitment and authorized revision.",production:"Update forecast and assign corrective action.",quality:"Keep lot on hold until independent QA release.",warehouse:"Reconcile receipt, lot identity, stock and evidence.",transport:"Confirm trip/checkpoint/ETA with responsible dispatcher.",port:"Obtain authoritative suitability and terminal confirmation.",loading:"Reconcile tally, survey and quantity basis with independent review.",vessel:"Confirm through authorized agent/provider and record source freshness.",documents:"Review checklist, version, expiry and source evidence.",customs:"Verify official declaration/status evidence; do not infer clearance.",settlement:"Reconcile obligation, payment and settlement evidence."};
const generatedFaultScenarios:SimScenario[]=allStages.flatMap((stage,stageIndex)=>faultStates.map((fault,faultIndex)=>{
 const stages:Partial<Record<SimStage,SimState>>=Object.fromEntries(allStages.map(s=>[s,"ready"])) as Record<SimStage,SimState>;
 stages[stage]=fault;
 const expectedOutcome:SimScenario["expectedOutcome"]=["blocked","missing","hold"].includes(fault)?"blocked":"review";
 return {simulationOnly:true as const,id:"SIM-"+String(166+stageIndex*faultStates.length+faultIndex).padStart(3,"0"),title:`Synthetic matrix: ${stageLabels[stage]} — ${fault}`,category:"synthetic-matrix",description:`Deterministic single-stage fault injection: ${stageLabels[stage]} is ${fault}; all other lifecycle stages are ready. This checks safe status propagation and next-action behavior.`,stages,expectedOutcome,persona:stagePersona[stage],userFacingMessage:`Status ${stageLabels[stage]}: ${fault}. Export readiness must not be inferred as ready.`,nextAction:stageActions[stage]};
}));
EXPORT_SIMULATION_SCENARIOS.push(...generatedFaultScenarios);
export const EXPORT_SIMULATION_SCENARIOS_EXTENDED=EXPORT_SIMULATION_SCENARIOS;
export const SIMULATION_STAGE_ORDER=allStages;
export function evaluateScenario(s:SimScenario):"ready"|"blocked"|"review"{
 const states=Object.values(s.stages);
 if(states.length===0)return "blocked";
 if(states.some(x=>x==="blocked"||x==="missing"||x==="hold"))return "blocked";
 if(states.some(x=>x==="mismatch"||x==="stale"||x==="pending"||x==="unverified"))return "review";
 if(states.some(x=>x==="not-run")||SIMULATION_STAGE_ORDER.some(stage=>!(stage in s.stages)))return "blocked";
 return "ready";
}
